// src/components/member-list.tsx
export function MemberList({ query }: { query: MembersQuery }) {
  const { data, isLoading, error } = query;
  if (isLoading) return <Skeleton rows={3} />;
  if (error) return <p className="text-danger">Could not load members.</p>;
  if (data.length === 0) return <p className="text-content-muted">No members yet.</p>;
  return (
    <ul className="divide-y divide-line bg-surface motion-safe:animate-fade-in dark:bg-slate-800">
      {data.map((member) => (
        <li key={member.id} className="flex items-center justify-between p-3">
          <span>{member.name}</span>
          <Button variant="ghost" onClick={() => removeMember(member.id)}>Remove</Button>
        </li>
      ))}
    </ul>
  );
}
```

